qasm_string = r'''OPENQASM 3.0;
include "stdgates.inc";
include "oracle.inc";
qubit[17] q;
bit[8] c;
h q[0];
h q[1];
h q[2];
h q[3];
h q[4];
h q[5];
h q[6];
h q[7];
Oracle q[0], q[1], q[2], q[3], q[4], q[5], q[6], q[7], q[8], q[9], q[10], q[11], q[12], q[13], q[14], q[15];
h q[0];
h q[1];
h q[2];
h q[3];
h q[4];
h q[5];
h q[6];
h q[7];
measure q[0] -> c[0];
measure q[1] -> c[1];
measure q[2] -> c[2];
measure q[3] -> c[3];
measure q[4] -> c[4];
measure q[5] -> c[5];
measure q[6] -> c[6];
measure q[7] -> c[7];
'''

code_string = r'''
from qiskit import transpile

def _gf2_rank(rows, n):
    basis = [0] * n
    rank = 0
    for v in rows:
        x = v
        while x:
            i = x.bit_length() - 1
            if basis[i]:
                x ^= basis[i]
            else:
                basis[i] = x
                rank += 1
                break
    return rank

def _gf2_nullspace_basis(rows, n):
    piv = [-1] * n
    basis = [0] * n
    for v in rows:
        x = v
        while x:
            i = x.bit_length() - 1
            if basis[i]:
                x ^= basis[i]
            else:
                basis[i] = x
                piv[i] = i
                break

    pivot_cols = [i for i in range(n) if basis[i] != 0]
    is_pivot = [False] * n
    for i in pivot_cols:
        is_pivot[i] = True

    null_basis = []
    for free in range(n):
        if is_pivot[free]:
            continue
        vec = 1 << free
        for i in pivot_cols:
            if (basis[i] >> free) & 1:
                vec ^= 1 << i
        null_basis.append(vec)
    return null_basis

def _popcount(x):
    return x.bit_count()

def _int_to_bitstring(x, n):
    return format(x, '0{}b'.format(n))

def run_and_analyze(circuit, aer_sim):
    n = 8
    shots = 8192

    tcirc = transpile(circuit, aer_sim, optimization_level=0)
    result = aer_sim.run(tcirc, shots=shots).result()
    counts = result.get_counts(tcirc)

    rows = []
    for bitstr, cnt in counts.items():
        if set(bitstr) == {'0'}:
            continue
        y = int(bitstr, 2)
        rows.extend([y] * cnt)

    # If extremely unlucky, supplement by running again
    if len(rows) < 256:
        result2 = aer_sim.run(tcirc, shots=shots).result()
        counts2 = result2.get_counts(tcirc)
        for bitstr, cnt in counts2.items():
            if set(bitstr) == {'0'}:
                continue
            y = int(bitstr, 2)
            rows.extend([y] * cnt)

    # Build a maximal independent set of equations y·s=0
    indep = []
    basis = [0] * n
    for v in rows:
        x = v
        while x:
            i = x.bit_length() - 1
            if basis[i]:
                x ^= basis[i]
            else:
                basis[i] = x
                indep.append(v)
                break
        if sum(1 for b in basis if b) >= n - 2:
            break

    # Try to ensure rank n-2 (so nullspace dimension 2)
    if _gf2_rank(indep, n) < n - 2:
        # Add more until saturation or enough
        for v in rows[len(indep):]:
            cur_rank = _gf2_rank(indep, n)
            if cur_rank >= n - 2:
                break
            indep.append(v)
        # reduce again to independent set
        filtered = []
        basis = [0] * n
        for v in indep:
            x = v
            while x:
                i = x.bit_length() - 1
                if basis[i]:
                    x ^= basis[i]
                else:
                    basis[i] = x
                    filtered.append(v)
                    break
        indep = filtered

    null_basis = _gf2_nullspace_basis(indep, n)

    # We expect dimension 2: solutions are {0, s1, s2, s1^s2}
    # If dimension >2, use additional equations to reduce
    if len(null_basis) > 2:
        eqs = indep[:]
        used = set(eqs)
        for v in rows:
            if v in used:
                continue
            eqs.append(v)
            nb = _gf2_nullspace_basis(eqs, n)
            if len(nb) == 2:
                indep = eqs
                null_basis = nb
                break
        # If still >2, take first two and proceed (best-effort)
        if len(null_basis) > 2:
            null_basis = null_basis[:2]

    if len(null_basis) == 0:
        prediction1 = '0' * n
        prediction2 = '0' * n
        return prediction1, prediction2

    if len(null_basis) == 1:
        a = null_basis[0]
        if a == 0:
            prediction1 = '0' * n
            prediction2 = '0' * n
        else:
            prediction1 = _int_to_bitstring(a, n)
            prediction2 = _int_to_bitstring(a, n)
        return prediction1, prediction2

    a, b = null_basis[0], null_basis[1]
    candidates = [a, b, a ^ b]
    candidates = [x for x in candidates if x != 0]
    # Prefer two with smallest Hamming weight (arbitrary but stable)
    candidates.sort(key=lambda x: (_popcount(x), x))
    if len(candidates) >= 2:
        s1, s2 = candidates[0], candidates[1]
    elif len(candidates) == 1:
        s1, s2 = candidates[0], candidates[0]
    else:
        s1, s2 = 0, 0

    prediction1 = _int_to_bitstring(s1, n)
    prediction2 = _int_to_bitstring(s2, n)
    return prediction1, prediction2
'''
END_FILE>>>

